// Contract designed to revert upon receiving ETH, controllable by the owner.
contract ControllableReverter {
    bool public shouldRevert = false;
    address public owner;

    constructor() {
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    function setRevert(bool _revert) public onlyOwner {
        shouldRevert = _revert;
    }

    fallback() external payable {
        if (shouldRevert) {
            revert("Reverting as requested");
        }
    }
}

